<?php
declare(strict_types=1); namespace Theobroma\OneC\Import;
final class SafeXml {public static function load(string$xml,int$limit=10485760):\SimpleXMLElement{if(strlen($xml)>$limit)throw new \InvalidArgumentException('XML exceeds configured limit');if(preg_match('/<!\s*(?:DOCTYPE|ENTITY)/i',$xml))throw new \InvalidArgumentException('Unsafe XML declarations are forbidden');$old=libxml_use_internal_errors(true);try{$root=simplexml_load_string($xml,\SimpleXMLElement::class,LIBXML_NONET|LIBXML_NOBLANKS);if(!$root instanceof \SimpleXMLElement)throw new \InvalidArgumentException('Malformed CommerceML XML');return$root;}finally{libxml_clear_errors();libxml_use_internal_errors($old);}}public static function value(\SimpleXMLElement$n,string$name):string{$v=$n->xpath('./*[local-name()="'.$name.'"]');return trim((string)($v[0]??''));}}
